CREATE TABLE IF NOT EXISTS continuum_economy_accounts(account_id uuid PRIMARY KEY,balance bigint NOT NULL DEFAULT 0,account_type smallint NOT NULL DEFAULT 0,created_utc timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_utc timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS continuum_economy_operations(operation_id uuid PRIMARY KEY,request_hash char(64) NOT NULL,operation_kind smallint NOT NULL,created_utc timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS continuum_economy_transactions(transaction_id uuid PRIMARY KEY,request_hash char(64) NOT NULL,sender_id uuid NOT NULL,receiver_id uuid NOT NULL,amount bigint NOT NULL,transaction_type integer NOT NULL,region_id uuid NOT NULL,object_id uuid NOT NULL,description varchar(255) NOT NULL DEFAULT '',status smallint NOT NULL,sender_balance bigint NOT NULL,receiver_balance bigint NOT NULL,failure_reason varchar(255) NOT NULL DEFAULT '',created_utc timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_sender_time ON continuum_economy_transactions(sender_id,created_utc);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_receiver_time ON continuum_economy_transactions(receiver_id,created_utc);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_type_time ON continuum_economy_transactions(transaction_type,created_utc);
CREATE TABLE IF NOT EXISTS continuum_economy_adjustments(operation_id uuid PRIMARY KEY,request_hash char(64) NOT NULL,account_id uuid NOT NULL,actor_id uuid NOT NULL,amount bigint NOT NULL,adjustment_kind smallint NOT NULL,transaction_type integer NOT NULL,reason varchar(255) NOT NULL,status smallint NOT NULL,resulting_balance bigint NOT NULL,failure_reason varchar(255) NOT NULL DEFAULT '',created_utc timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_adjustment_account_time ON continuum_economy_adjustments(account_id,created_utc);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_adjustment_actor_time ON continuum_economy_adjustments(actor_id,created_utc);
CREATE TABLE IF NOT EXISTS continuum_economy_purchases(purchase_id uuid PRIMARY KEY,request_hash char(64) NOT NULL,buyer_id uuid NOT NULL,seller_id uuid NOT NULL,amount bigint NOT NULL,transaction_type integer NOT NULL,region_id uuid NOT NULL,object_id uuid NOT NULL,description varchar(255) NOT NULL DEFAULT '',state smallint NOT NULL,buyer_balance bigint NOT NULL,seller_balance bigint NOT NULL,failure_reason varchar(255) NOT NULL DEFAULT '',created_utc timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_utc timestamptz NULL);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_purchase_buyer_state ON continuum_economy_purchases(buyer_id,state);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_purchase_seller_time ON continuum_economy_purchases(seller_id,created_utc);
CREATE TABLE IF NOT EXISTS continuum_economy_account_registrations(operation_id uuid PRIMARY KEY,request_hash char(64) NOT NULL,account_id uuid NOT NULL,actor_id uuid NOT NULL,account_type smallint NOT NULL,display_name varchar(255) NOT NULL,created_utc timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_registration_account ON continuum_economy_account_registrations(account_id);
